<script setup lang="ts">
import {onMounted,onUnmounted,ref,shallowRef,watch} from 'vue';
import type {ActionResult} from '../../src/full/contracts.ts';
import {createEffectTracker,type EffectNotice} from './effects';
const emit=defineEmits<{ 'focus-fallback':[] }>();
const root=ref<HTMLElement>();
const props=defineProps<{result:ActionResult|null;replayed:boolean;runId:string;revision:number;school:'sword'|'talisman'|null;reduceMotion:boolean;busy:boolean;eligible:boolean}>();
const notice=shallowRef<EffectNotice|null>(null),media=window.matchMedia('(prefers-reduced-motion: reduce)'),systemReduced=ref(media.matches),tracker=createEffectTracker();let timer:ReturnType<typeof setTimeout>|undefined;
function finish(){const owned=!!root.value?.contains(document.activeElement);if(timer)clearTimeout(timer);timer=undefined;notice.value=null;if(owned)queueMicrotask(()=>{if(document.activeElement===document.body)emit('focus-fallback');});}
function holdFocus(){if(timer)clearTimeout(timer);timer=undefined;}
function leaveFocus(){queueMicrotask(()=>{if(root.value&&!root.value.contains(document.activeElement))finish();});}
function mediaChange(){systemReduced.value=media.matches;}
onMounted(()=>media.addEventListener('change',mediaChange));onUnmounted(()=>{media.removeEventListener('change',mediaChange);finish();});
watch(()=>[props.result,props.replayed,props.runId,props.revision,props.school,props.busy,props.eligible] as const,()=>{finish();if(props.busy||!props.eligible)return;const next=tracker.consume(props.result,props.replayed,props.runId,props.revision,props.school);if(next&&!props.reduceMotion&&!systemReduced.value){notice.value=next;timer=setTimeout(finish,2200);}},{immediate:true});
watch(()=>props.reduceMotion||systemReduced.value,value=>{if(value)finish();});
</script>
<template><div v-if="notice" ref="root" :key="notice.key" class="action-effect" @focusin="holdFocus" @focusout="leaveFocus" :class="[notice.group,notice.school]" :data-group="notice.group" :data-receipt="notice.key" data-testid="action-effect" role="status">
<svg viewBox="0 0 120 80" aria-hidden="true" focusable="false"><g class="effect-art"><circle v-if="notice.group==='entry'||notice.group==='breakthrough'" cx="60" cy="40" r="27"/><path v-if="notice.group==='entry'" d="M28 60Q60 34 92 60M38 57Q60 16 82 57M60 17v40"/><path v-else-if="notice.group==='breakthrough'" d="m60 9 9 22 24 9-24 9-9 22-9-22-24-9 24-9Z"/><path v-else-if="notice.group==='trial'" d="M34 67V19h52v48M27 19h66M44 28h32v39M60 28v39M20 70h80m-9-67-9 14 9-2-10 15"/><path v-else-if="notice.school==='sword'" d="M35 67 82 11l-4 20-31 34M33 53l20 17M24 21q25-18 50 0M19 38q24-14 43-7"/><path v-else d="m39 13 48 5-6 53-48-5Zm8 14 24 3m-25 9 20 3m-22 9 24 3M22 14l5 7m66 31 7 3"/></g></svg>
<div><strong>{{notice.label}}</strong><small>进度已保存</small></div><button type="button" data-testid="fx-skip" @click="finish" aria-label="跳过本次演出">跳过</button></div></template>
<style scoped>.action-effect{position:absolute;top:12px;right:12px;z-index:4;display:flex;align-items:center;gap:10px;width:min(340px,calc(100% - 24px));padding:10px 12px;background:#fcf6e9f5;border:1px solid #a38a54;box-shadow:0 7px 24px #173c3944;pointer-events:none;animation:effect-fade 2.2s both}.action-effect svg{width:80px;height:60px;flex-shrink:0;fill:none;stroke:#8b733c;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.effect-art{transform-origin:60px 40px;animation:effect-reveal .65s ease-out both}.action-effect strong{font-size:calc(0.88888889rem * var(--font-scale,1));color:#294746}.action-effect small{display:block;font-size:calc(0.72222222rem * var(--font-scale,1));margin-top:5px}.action-effect button{margin-left:auto;padding:6px;font-size:calc(0.72222222rem * var(--font-scale,1));pointer-events:auto}.trial svg{stroke:#586969}.battle.sword svg{stroke:#496c65}.battle.talisman svg{stroke:#9a7851}@keyframes effect-reveal{from{opacity:0;transform:scale(.65)}to{opacity:1;transform:scale(1)}}@keyframes effect-fade{0%{opacity:0}12%,78%{opacity:1}100%{opacity:0}}@media(prefers-reduced-motion:reduce){.action-effect{display:none;animation:none}.effect-art{animation:none}}.action-effect>div{min-width:0;flex:1}.action-effect strong{display:block;overflow-wrap:anywhere}.action-effect button{flex-shrink:0;min-width:44px}.action-effect:focus-within{animation:none;opacity:1}.action-effect:focus-within .effect-art{animation:none;opacity:1;transform:none}
</style>
